#!/usr/bin/env bash
# Run from inside Laravel project: bash scripts/adjust-seo-metadata.sh
# Self-contained SEO metadata deployment for the public site.
# Carries final SEO-adjusted files as embedded base64 blobs and writes them
# into the project (no git required — deploy-copy safe). Idempotent.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APP_ROOT="$SCRIPT_DIR"
while [ ! -f "$APP_ROOT/artisan" ] && [ "$APP_ROOT" != "/" ]; do
    APP_ROOT="$(dirname "$APP_ROOT")"
done
if [ ! -f "$APP_ROOT/artisan" ]; then
    echo "Could not locate artisan (looked upward from $SCRIPT_DIR). Run from inside the Laravel project." >&2
    exit 1
fi
cd "$APP_ROOT"

apply_blob() {
    local path="$1" b64name="$2"
    mkdir -p "$(dirname "$path")"
    local tmp
    tmp="$(mktemp)"
    if printf '%s' "${!b64name}" | base64 --decode > "$tmp" 2>/dev/null; then
        if [ -f "$path" ]; then cp "$path" "$path.seo.bak"; fi
        mv "$tmp" "$path"
        echo "Installed: $path"
    else
        echo "Failed to decode blob for $path" >&2
        rm -f "$tmp"
    fi
}

B64_
apply_blob resources/views/components/site-layout.blade.php B64_0
B64_
apply_blob resources/views/public/home.blade.php B64_1
B64_
apply_blob resources/views/public/blog/show.blade.php B64_2
B64_
apply_blob public/assets/site/style.css B64_3
B64_
apply_blob public/assets/images/og-image.jpg B64_OG
php artisan optimize:clear >/dev/null
echo "Done: SEO metadata deployment applied (backups saved as *.seo.bak)."
